//! AppImage start-up: use the system's `libwayland-client`.
//!
//! The AppImage is built on an older distribution and bundles that system's
//! `libwayland-client`, but the graphics driver always comes from the host. A
//! newer host Mesa needs symbols the bundled library lacks, so `WebKitGTK`
//! aborts with `EGL_BAD_PARAMETER` and the window stays grey. `AppRun` and its
//! hooks are generated by linuxdeploy, so the process restarts itself once with
//! the system library preloaded. A host without the library keeps the bundled one.

use std::env;
use std::ffi::{OsStr, OsString};
use std::os::unix::process::CommandExt;
use std::path::{Path, PathBuf};
use std::process::Command;

const LIBRARY: &str = "libwayland-client.so.0";
const LIBRARY_DIRS: [&str; 3] = ["/usr/lib/x86_64-linux-gnu", "/usr/lib64", "/usr/lib"];
/// Set on the restarted process, so it does not restart again. Setting it
/// beforehand turns the restart off.
const GUARD: &str = "KAIKU_APPIMAGE_SYSTEM_WAYLAND";

/// Restarts the process with the system library preloaded when it runs from an
/// AppImage. Returns only if no restart is needed or it failed.
pub fn prefer_system_wayland() {
    if env::var_os("APPDIR").is_none() || env::var_os(GUARD).is_some() {
        return;
    }
    let Some(library) = find_library(&LIBRARY_DIRS) else {
        return;
    };
    let Ok(exe) = env::current_exe() else {
        return;
    };
    let mut args = env::args_os();
    let mut command = Command::new(exe);
    if let Some(arg0) = args.next() {
        command.arg0(arg0);
    }
    let error = command
        .args(args)
        .env(GUARD, "1")
        .env(
            "LD_PRELOAD",
            preload_value(env::var_os("LD_PRELOAD").as_deref(), &library),
        )
        .exec();
    eprintln!("Could not restart with the system {LIBRARY}: {error}");
}

fn find_library(dirs: &[&str]) -> Option<PathBuf> {
    dirs.iter()
        .map(|dir| Path::new(dir).join(LIBRARY))
        .find(|path| path.exists())
}

fn preload_value(existing: Option<&OsStr>, library: &Path) -> OsString {
    let mut value = library.as_os_str().to_owned();
    if let Some(existing) = existing.filter(|e| !e.is_empty()) {
        value.push(":");
        value.push(existing);
    }
    value
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preload_puts_the_library_first_and_keeps_existing_entries() {
        let library = Path::new("/usr/lib/libwayland-client.so.0");
        assert_eq!(preload_value(None, library), library.as_os_str());
        assert_eq!(
            preload_value(Some(OsStr::new("")), library),
            library.as_os_str()
        );
        assert_eq!(
            preload_value(Some(OsStr::new("/opt/other.so")), library),
            OsStr::new("/usr/lib/libwayland-client.so.0:/opt/other.so")
        );
    }

    #[test]
    fn find_library_takes_the_first_directory_that_has_it() {
        let empty = tempfile::tempdir().unwrap();
        let first = tempfile::tempdir().unwrap();
        let second = tempfile::tempdir().unwrap();
        std::fs::write(first.path().join(LIBRARY), b"").unwrap();
        std::fs::write(second.path().join(LIBRARY), b"").unwrap();
        let dirs = [
            empty.path().to_str().unwrap(),
            first.path().to_str().unwrap(),
            second.path().to_str().unwrap(),
        ];
        assert_eq!(find_library(&dirs), Some(first.path().join(LIBRARY)));
        assert_eq!(find_library(&dirs[..1]), None);
    }
}
